  ["block and proc invocation (generic)",
   /\A(vm_invoke_|rb_vm_invokeblock|vm_yield|rb_yield|invoke_block|invoke_iseq_block|vm_callee_setup_block_arg|rb_vm_bh_to_procval|vm_block_handler|rb_vm_yield|vm_caller_setup_arg_block|rb_vm_invoke_proc|rb_proc_call|proc_call|vm_call_opt_call|vm_call_opt_block_call|rb_block_|vm_make_proc|rb_vm_make_proc|rb_func_proc_call|rb_vm_ifunc|bmcall|vm_ifunc|rb_iterate|rb_block_call|rb_lambda_call|iterate_method|rb_vm_block_|vm_block_)/],
